import { _decorator, Component, Sprite, SpriteFrame, CCInteger, Enum, gfx, Material } from 'cc';
const { ccclass, property, executeInEditMode } = _decorator;

@ccclass('SkinController')
@executeInEditMode(true) //에디터 모드에서도 코드 동작시키자
export class SkinController extends Component {

    // 인스펙터에 노출하자
    @property([SpriteFrame]) 
    public frames: SpriteFrame[] = [];

    @property
    private _currSkinIdx: number = 0;

    // 💡 에디터 인스펙터에서 SkinMaterial.mtl을 여기에 드래그해서 넣어주세요.
    @property(Material)
    public skinMaterial: Material | null = null;

    // 2. 위에서 정의한 Enum을 타입으로 사용합니다.
    @property({ type: Enum(gfx.BlendFactor), displayName: 'Src Blend' })
    srcBlend: number = gfx.BlendFactor.SRC_ALPHA;
    
    @property({ type: Enum(gfx.BlendFactor), displayName: 'Dst Blend' })
    dstBlend: number = gfx.BlendFactor.ONE_MINUS_SRC_ALPHA;

    @property({ type: CCInteger, 
        displayName: 'Current Skin Index', 
        step:1, 
        min :0,
        tooltip: 'toolip sample...' 
    })
    get currentSkinIndex() {
        return this._currSkinIdx;
    }
    set currentSkinIndex(value: number) {
        // 범위를 frames의 개수 안으로 강제 제한 (Clamp)
        const safeIdx = Math.max(0, Math.min(value, this.frames.length - 1));

        this._currSkinIdx = safeIdx; // 실제 내부 값도 보정된 값으로 저장
        this.setBoneSkinIndex( safeIdx ); // 스킨 적용
    }
    
    public setBoneSkinIndex(index: number ) {
        if (index < 0 || index >= this.frames.length) return;

        const sprite = this.getComponent(Sprite);
        if (sprite && this.frames[index]) {
            sprite.spriteFrame = this.frames[index];
            
            // 💡 블렌딩 설정이 필요한 경우 (예: srcBlend가 Normal(2)이 아닌 경우)
            if (this.srcBlend !== 2 || this.dstBlend !== 4) {
                // 커스텀 재질 적용 및 수치 주입
                if (this.skinMaterial) {
                    // 재질의 인스턴스를 생성하여 해당 노드만 독립적으로 블렌딩 변경
                    const matInstance = sprite.getMaterialInstance(0) || this.skinMaterial;
                    sprite.customMaterial = matInstance;

                    const pass = matInstance.passes[0];
                    const target = pass.blendState.targets[0];
                    target.blend = true;
                    target.blendSrc = this.srcBlend;
                    target.blendDst = this.dstBlend;
                    pass.update();
                }
            } else {
                // Normal 모드라면 기본 재질로 복구
                sprite.customMaterial = null;
            }
            sprite.markForUpdateRenderData();
        }
    }
}